select name, d, status, row_number() over (partition by name order by d) 
                      - row_number() over (partition by name, status order by d) as grp 
from (
    select nc.name, nc.d, a.date, a.name as aname
         , coalesce(a.status, 'present') as status        
    from ( 
        select distinct d, name 
        from calendar c cross join attendance a
    ) as nc
    left join attendance a                                                       
        on a.name = nc.name
        and a.date = nc.d
)

select  id
       ,regexp_replace(str,'^([^\.]+\.?){' || gs.i || '}','') as suffix

from    t,generate_series(0,cardinality(string_to_array(str,'.'))-1) gs(i)

select  id
       ,substring(str from '(([^.]*?\.?){' || gs.i+1 || '})$') as suffix

from    t,generate_series(0,cardinality(string_to_array(str,'.'))-1) gs(i)

select      id
           ,array_to_string((string_to_array(str,'.'))[i:],'.')

from        t,unnest(string_to_array(str,'.')) with ordinality u(token,i)

select id, work
from (
  select id, work, row_number() over (order by work) as rn
  from x
) t
where rn = 1 -- or 2 or 3 ...

select count(*) week_days
from (
  select 
    getdate()+dt, 
    extract(dow from getdate()+dt) dow
  from(
    select 
      generate_series(
        1,
        datediff('days', getdate(), '2023-07-11 00:00:00.000'),
        1
      ) as dt
  )
) 
where dow not in (0, 6)

select vendor, min(startdate) as startdate, max(enddate) as enddate, grp
from (
      select vendor, auth, startdate, enddate, 
             sum(rst) over (order by vendor, startdate) as grp
      from (
             select vendor, auth, startdate, enddate, 
                    case when coalesce(lag(enddate) over (partition by vendor order by vendor, startdate), startdate) + 1 <> startdate then 1 end rst
             from   tbl
           ) t1
     ) t2
group by grp, vendor
order by startdate

select a.x, b.y
