select id, a, first_value(b) over (partition by grp) as b, c
from (
      select id, a, b, c, 
             sum(case when b is not null then 1 end) over (order by id) as grp
      from   tbl
     ) t

select SL.*, S.qty_
from
(
  select *
  from (
    select distinct date_ from sales
  ) S_ cross join (
    select distinct name from locations
  ) L_
) SL left join (
  select date_, location_, qty_ from sales
) S on SL.name = S.location_ and SL.date_ = S.date_ 
order by SL.date_, SL.name

select foo.id, x.*
from foo, jsonb_each_text(to_jsonb(foo)) as x(colname,colvalue)
where x.colname ~ '^[a-z]$'

select max(actors_comparing.counta)
from (
  SELECT fa1.actor_id first_actor, fa2.actor_id second_actor, count(*) counta
  FROM film_actor fa1
  join film_actor fa2
  using (film_id)
  where fa1.actor_id != fa2.actor_id
  group by (fa1.actor_id, fa2.actor_id)
) actors_comparing

select actors_comparing.first_actor, actors_comparing.second_actor, max(actors_comparing.counta)
from (
  SELECT fa1.actor_id first_actor, fa2.actor_id second_actor, count(*) counta
  FROM film_actor fa1
  join film_actor fa2
  using (film_id)
  where fa1.actor_id != fa2.actor_id
  group by (fa1.actor_id, fa2.actor_id)
) actors_comparing

